CREATE TYPE public.app_role AS ENUM ('super_admin','company_owner','general_manager','branch_manager','supervisor','forex_teller','mobile_money_teller','accountant','auditor');
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own_read ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id = r.user_id WHERE r.user_id = _user_id AND r.role = _role AND p.active) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE FUNCTION public.is_staff_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'company_owner') $$;
REVOKE ALL ON FUNCTION public.is_staff_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_staff_admin() TO authenticated,service_role;
CREATE POLICY profiles_admin_read ON public.profiles FOR SELECT TO authenticated USING(public.is_staff_admin());
CREATE POLICY profiles_admin_update ON public.profiles FOR UPDATE TO authenticated USING(public.is_staff_admin()) WITH CHECK(public.is_staff_admin());
CREATE POLICY roles_admin_manage ON public.user_roles FOR ALL TO authenticated USING(public.is_staff_admin()) WITH CHECK(public.is_staff_admin());
CREATE TABLE public.branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, address text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.branches TO authenticated;
GRANT ALL ON public.branches TO service_role;
ALTER TABLE public.branches ENABLE ROW LEVEL SECURITY;
CREATE POLICY branches_admin_manage ON public.branches FOR ALL TO authenticated USING(public.is_staff_admin()) WITH CHECK(public.is_staff_admin());
CREATE TABLE public.branch_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES public.branches(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,branch_id));
GRANT SELECT, INSERT, DELETE ON public.branch_assignments TO authenticated;
GRANT ALL ON public.branch_assignments TO service_role;
ALTER TABLE public.branch_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY assignments_own_read ON public.branch_assignments FOR SELECT TO authenticated USING(user_id = auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE id = auth.uid() AND active));
CREATE POLICY assignments_admin_manage ON public.branch_assignments FOR ALL TO authenticated USING(public.is_staff_admin()) WITH CHECK(public.is_staff_admin());
CREATE POLICY branches_assigned_read ON public.branches FOR SELECT TO authenticated USING(active AND EXISTS(SELECT 1 FROM public.branch_assignments a WHERE a.branch_id = branches.id AND a.user_id = auth.uid()));
CREATE FUNCTION public.create_staff_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_staff_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER on_findesk_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_staff_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT(id) DO NOTHING;
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER roles_updated BEFORE UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER branches_updated BEFORE UPDATE ON public.branches FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER assignments_updated BEFORE UPDATE ON public.branch_assignments FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE INDEX assignments_branch_idx ON public.branch_assignments(branch_id);
CREATE FUNCTION public.save_staff_access(_user_id uuid,_display_name text,_active boolean,_roles public.app_role[],_branches uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
IF NOT public.is_staff_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _user_id = auth.uid() THEN RAISE EXCEPTION 'Administrators cannot change their own access'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id = _user_id) THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
IF EXISTS(SELECT 1 FROM unnest(_branches) b WHERE NOT EXISTS(SELECT 1 FROM public.branches WHERE id = b AND active)) THEN RAISE EXCEPTION 'Invalid or inactive branch'; END IF;
UPDATE public.profiles SET display_name = trim(_display_name),active = _active WHERE id = _user_id;
DELETE FROM public.user_roles WHERE user_id = _user_id;
INSERT INTO public.user_roles(user_id,role) SELECT _user_id,r FROM (SELECT DISTINCT unnest(_roles) r) roles;
DELETE FROM public.branch_assignments WHERE user_id = _user_id;
INSERT INTO public.branch_assignments(user_id,branch_id) SELECT _user_id,b FROM (SELECT DISTINCT unnest(_branches) b) branches;
END $$;
REVOKE ALL ON FUNCTION public.save_staff_access(uuid,text,boolean,public.app_role[],uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_staff_access(uuid,text,boolean,public.app_role[],uuid[]) TO authenticated;
-- Direct access edits cannot bypass atomic access management or self-change protection.
REVOKE INSERT, UPDATE, DELETE ON public.user_roles FROM authenticated;
REVOKE INSERT, DELETE ON public.branch_assignments FROM authenticated;
REVOKE UPDATE ON public.profiles FROM authenticated;
